settings.customCss:
.mfp-easter-blossom-atelier{--mf-surface:#fffdfd;--mf-ink:#302731;--mf-muted:#6e606b;--mf-line:#d9c9d0;--mf-control:#ffffff;--mf-action:#70384d;--mf-action-ink:#ffffff;--mf-focus:#2c7370;--mf-error:#ad273d;--mf-tint:#f7eef2;box-sizing:border-box;width:100%;max-width:720px;margin:0 auto;border:1px solid var(--mf-line);border-radius:6px;overflow:hidden;background:var(--mf-surface);color:var(--mf-ink);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;font-size:16px;line-height:1.5;letter-spacing:0}
.mfp-easter-blossom-atelier *{box-sizing:border-box;min-width:0}
.mfp-easter-blossom-atelier .form-header img{display:block;width:100%;height:170px;object-fit:cover;object-position:center 57%}
.mfp-easter-blossom-atelier .form-heading{padding:24px 36px 0}
.mfp-easter-blossom-atelier .form-kicker{margin:0 0 8px;color:var(--mf-action);font-size:12px;font-weight:650}
.mfp-easter-blossom-atelier h2{margin:0 0 9px;font-family:Georgia,"Times New Roman",serif;font-size:34px;line-height:1.15;font-weight:400;overflow-wrap:anywhere}
.mfp-easter-blossom-atelier .form-heading p:last-child{margin:0;color:var(--mf-muted);font-size:14px}
.mfp-easter-blossom-atelier .form-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 20px;padding:24px 36px 0}
.mfp-easter-blossom-atelier .question-heading{grid-column:1 / -1;display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--mf-line);padding-bottom:10px}
.mfp-easter-blossom-atelier .question-heading span{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;flex-shrink:0;border-radius:50%;background:var(--mf-tint);color:var(--mf-action);font-size:11px;font-weight:650}
.mfp-easter-blossom-atelier h3{margin:0;font-size:14px;font-weight:650}
.mfp-easter-blossom-atelier .field-wide{grid-column:1 / -1}
.mfp-easter-blossom-atelier .field-slot{overflow-wrap:anywhere}
.mfp-easter-blossom-atelier .field-slot label{display:block;margin-bottom:7px;font-size:13px;font-weight:600;color:var(--mf-ink)}
.mfp-easter-blossom-atelier .field-slot small{display:block;margin-top:6px;color:var(--mf-muted);font-size:12px}
.mfp-easter-blossom-atelier .form-actions{padding:24px 36px 0}
.mfp-easter-blossom-atelier .form-actions button{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:50px;gap:12px;padding:12px 18px;border:0;border-radius:4px;background:var(--mf-action);color:var(--mf-action-ink);font:inherit;font-size:14px;font-weight:600;cursor:pointer}
.mfp-easter-blossom-atelier .form-actions button span{font-size:20px}
.mfp-easter-blossom-atelier .form-actions button:hover{filter:brightness(1.08)}
.mfp-easter-blossom-atelier .form-actions button:disabled{opacity:0.65;cursor:wait}
.mfp-easter-blossom-atelier .form-footer{padding:14px 36px 24px;font-size:12px;text-align:center;color:var(--mf-muted)}
.mfp-easter-blossom-atelier .field-slot [aria-invalid="true"]{border-color:var(--mf-error)}
.mfp-easter-blossom-atelier .field-slot [role="alert"]{color:var(--mf-error);font-size:13px;margin-top:6px}
.mfp-easter-blossom-atelier [role="status"]{color:var(--mf-ink);overflow-wrap:anywhere}
.mfp-easter-blossom-atelier .field-slot input{display:block;width:100%;min-height:46px;padding:10px 12px;border:1px solid var(--mf-line);border-radius:4px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-blossom-atelier .field-slot input:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-blossom-atelier .field-slot input::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-blossom-atelier .field-slot select{display:block;width:100%;min-height:46px;padding:10px 12px;border:1px solid var(--mf-line);border-radius:4px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-blossom-atelier .field-slot select:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-blossom-atelier .field-slot textarea{display:block;width:100%;min-height:88px;padding:10px 12px;border:1px solid var(--mf-line);border-radius:4px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px;resize:vertical}
.mfp-easter-blossom-atelier .field-slot textarea:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-blossom-atelier .field-slot textarea::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-blossom-atelier .form-actions button:focus-visible{outline:3px solid var(--mf-focus);outline-offset:3px}
@media(max-width:600px){.mfp-easter-blossom-atelier .form-header img{height:132px}.mfp-easter-blossom-atelier .form-heading{padding:20px 20px 0}.mfp-easter-blossom-atelier h2{font-size:29px}.mfp-easter-blossom-atelier .form-fields{grid-template-columns:1fr;gap:17px;padding:22px 20px 0}.mfp-easter-blossom-atelier .form-actions{padding:22px 20px 0}.mfp-easter-blossom-atelier .form-footer{padding:14px 20px 22px}}
